#include <iostream>
#include <algorithm>
#include <vector>
#include <cstring>

using namespace std;

const int MAXN = 450 + 30;

int n;
bool mark[MAXN];
vector<int> adj[MAXN], sadj[MAXN];
vector<int> st;
vector<int> comp[3];
int col[MAXN];

void dfs(int v) {
    if (mark[v])
        return;

    mark[v] = true;

    for (int u : adj[v])
        dfs(u);

    st.push_back(v);
}

bool cmp(int a, int b) {
    return col[a] < col[b];
}

int get(int s) {
    int ret = 0, cn = 0;
    memset(mark, 0, sizeof(mark));

    for (; cn < n; s = (s + 1) % 3, ret++) {
        for (int uu : comp[s]) {
            if (mark[uu])
                continue;

            bool flag = true;
            for (int vv : sadj[uu]) {
                if (!mark[vv]) {
                    flag = false;
                    break;
                }
            }

            if (flag) {
                mark[uu] = true;
                cn++;
            }
        }
    }

    return ret - 1 + n;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    for (int i = 0; i < n; i++) {
        int temp;
        cin >> temp;
        comp[--temp].push_back(i);
    }

    for (int i = 0; i < n; i++) {
        int t;
        cin >> t;

        while (t--) {
            int v;
            cin >> v;
            --v;
            adj[v].push_back(i);
            sadj[i].push_back(v);
        }
    }

    for (int i = 0; i < n; i++) {
        if (!mark[i])
            dfs(i);
    }

    reverse(st.begin(), st.end());

    for (int i = 0; i < static_cast<int>(st.size()); i++)
        col[st[i]] = i;

    for (int i = 0; i < 3; i++)
        sort(comp[i].begin(), comp[i].end(), cmp);

    int ans = min({get(0), get(1), get(2)});
    cout << ans << '\n';

    return 0;
}

